[{"order":1,"type":"heading","text":"Instrumented Tests with Espresso and UI Automator in Android (Kotlin)"},{"order":2,"type":"paragraph","text":"Testing user interfaces is a critical part of Android app development. While unit tests verify business logic in isolation, instrumented tests ensure that your UI components interact correctly and provide a seamless user experience. This tutorial explores how to combine Espresso and UI Automator to build robust, end-to-end UI tests in Kotlin."},{"order":3,"type":"subheading","text":"Understanding the Tools"},{"order":4,"type":"bullet_point","text":"Espresso: Designed for writing UI tests within a single app. It allows you to interact with UI elements inside your application package, checking states and performing actions with high speed and synchronization."},{"order":5,"type":"bullet_point","text":"UI Automator: A cross-app testing framework suitable for functional UI testing across system and third-party apps. It allows you to interact with the device's home screen, settings, or system notifications."},{"order":6,"type":"subheading","text":"Step 1: Adding Dependencies"},{"order":7,"type":"paragraph","text":"Open your module-level build.gradle.kts file and add the required testing dependencies inside the defaultConfig and dependencies blocks."},{"order":8,"type":"code","text":"android {
    defaultConfig {
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }
}

dependencies {
    androidTestImplementation("androidx.test.ext:junit:1.1.5")
    androidTestImplementation("androidx.test.espresso:espresso-core:3.5.1")
    androidTestImplementation("androidx.test.uiautomator:uiautomator:2.2.0")
}"},{"order":9,"type":"subheading","text":"Step 2: Writing a Hybrid Test"},{"order":10,"type":"paragraph","text":"Create a new test file named HybridUiTest.kt inside the androidTest directory. In this example, we will use Espresso to interact with our app's login screen and UI Automator to handle a system-level permission dialog."},{"order":11,"type":"code","text":"package com.example.myapp

import androidx.test.espresso.Espresso.onView
import androidx.test.espresso.action.ViewActions.*
import androidx.test.espresso.matcher.ViewMatchers.*
import androidx.test.ext.junit.rules.ActivityScenarioRule
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import androidx.test.uiautomator.UiDevice
import androidx.test.uiautomator.UiSelector
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class HybridUiTest {

    @get:Rule
    val activityRule = ActivityScenarioRule(MainActivity::class.java)

    @Test
    fun testLoginAndSystemPermission() {
        // Step 1: Use Espresso to type credentials and click login
        onView(withId(R.id.usernameEditText))
            .perform(typeText("test_user"), closeSoftKeyboard())

        onView(withId(R.id.passwordEditText))
            .perform(typeText("secure_password"), closeSoftKeyboard())

        onView(withId(R.id.loginButton))
            .perform(click())

        // Step 2: Use UI Automator to interact with a system notification or permission dialog
        val device = UiDevice.getInstance(InstrumentationRegistry.getInstrumentation())

        // Find and click the 'Allow' button on a system permission dialog
        val allowButton = device.findObject(UiSelector().textMatches("(?i)Allow"))
        if (allowButton.exists()) {
            allowButton.click()
        }
    }
}"},{"order":12,"type":"subheading","text":"Best Practices for Reliable Tests"},{"order":13,"type":"bullet_point","text":"Avoid Thread.sleep(): Rely on Espresso's built-in idling resources and synchronization instead of hardcoded sleeps."},{"order":14,"type":"bullet_point","text":"Combine Frameworks Wisely: Use Espresso for fast intra-app actions and UI Automator strictly when crossing app boundaries or handling OS-level interactions."},{"order":15,"type":"bullet_point","text":"Disable System Animations: Turn off animations in your test device settings to prevent flaky test executions caused by transition delays."}]
